    SELECT `id`, `title`, `thumb_image`, `services`, `client`, 
           `file_attach1`, `file_attach2`, ..., `file_attach5`, ...
    FROM `nb_works`
    WHERE `id` = :id AND `is_visible` = 1 AND `deleted_at` IS NULL
    SQL;
