4	
5	final class DB
6	{
7	    /** @var \PDO|null */
8	    private static $instance = null;
9	
10	    public static function getInstance(): \PDO
11	    {
12	        if (self::$instance instanceof \PDO) {
13	            return self::$instance;
14	        }
15	
16	        $configuration = self::configuration();
17	        self::$instance = self::connect($configuration);
18	
19	        return self::$instance;
20	    }
21	
22	    public static function makeSlug(string $title): string
23	    {
24	        $value = html_entity_decode($title, ENT_QUOTES | ENT_HTML5, 'UTF-8');
25	        if (class_exists('\Normalizer')) {
26	            $value = \Normalizer::normalize($value, \Normalizer::FORM_KC);
27	        }
28	
29	        $value = preg_replace('/["\'\x{2018}\x{2019}\x{201C}\x{201D}`]/u', '', $value);
30	        $value = preg_replace('/[\x{00A0}\s]+/u', ' ', $value);
31	        $value = preg_replace('/[^가-힣a-zA-Z0-9.\- ]/u', '', $value);
32	        $value = preg_replace('/\s+/u', '-', trim($value));
33	        $value = preg_replace('/-+/', '-', $value);
34	        $value = trim($value, '-');
35	
36	        return mb_strtolower($value, 'UTF-8');
37	    }
38	
39	    private static function configuration(): array
40	    {
41	        $host = defined('DB_HOST') ? (string) DB_HOST : 'db';
42	        $port = defined('DB_PORT') ? (int) DB_PORT : 3306;
43	        $name = defined('DB_NAME') ? (string) DB_NAME : '';
44	        $user = defined('DB_USER') ? (string) DB_USER : '';
45	        $pass = defined('DB_PASS') ? (string) DB_PASS : '';
46	        $charset = defined('DB_CHARSET') ? (string) DB_CHARSET : 'utf8mb4';
47	        $socket = defined('DB_UNIX_SOCKET') ? (string) DB_UNIX_SOCKET : '';
48	
49	        if ($name === '') {
50	            throw new \RuntimeException('Database name is not configured.');
51	        }
52	
53	        if ($user === '') {
54	            throw new \RuntimeException('Database user is not configured.');
55	        }
56	
57	        return [
58	            'host' => $host,
59	            'port' => $port,
60	            'name' => $name,
61	            'user' => $user,
62	            'pass' => $pass,
63	            'charset' => $charset,
64	            'socket' => $socket,
65	        ];
66	    }
67	
68	    private static function connect(array $configuration): \PDO
69	    {
70	        $dsn = self::dsn($configuration);
71	        $options = [
72	            \PDO::ATTR_ERRMODE => \PDO::ERRMODE_EXCEPTION,
73	            \PDO::ATTR_DEFAULT_FETCH_MODE => \PDO::FETCH_ASSOC,
74	            \PDO::ATTR_EMULATE_PREPARES => false,
75	            \PDO::ATTR_PERSISTENT => false,
76	        ];
77	
78	        try {
79	            return new \PDO($dsn, $configuration['user'], $configuration['pass'], $options);
80	        } catch (\PDOException $error) {
81	            error_log('[DB] Connection failed: ' . $error->getMessage());
82	            throw new \RuntimeException('Database connection failed.', 0, $error);
83	        }
84	    }
85	
86	    private static function dsn(array $configuration): string
87	    {
88	        if ($configuration['socket'] !== '') {
89	            return sprintf(
90	                'mysql:unix_socket=%s;dbname=%s;charset=%s',
91	                $configuration['socket'],
92	                $configuration['name'],
93	                $configuration['charset']
94	            );
95	        }
96	
97	        return sprintf(
98	            'mysql:host=%s;port=%d;dbname=%s;charset=%s',
99	            $configuration['host'],
100	            $configuration['port'],
101	            $configuration['name'],
102	            $configuration['charset']
103	        );
104	    }
105	}
