docker compose exec -T web bash -lc 'cd /var/www/html && php -r "
require \"config/setup.php\"; require \"src/Database/DB.php\";
\$pdo = \\Database\\DB::getInstance();
\$cols = [\"thumb_image\",\"file_attach1\",\"file_attach2\",\"file_attach3\",\"file_attach4\",\"file_attach5\"];
\$referenced = [];
foreach (\$pdo->query(\"SELECT \" . implode(\",\", \$cols) . \" FROM nb_works\") as \$r) {
    foreach (\$cols as \$c) {
        \$v = trim((string)(\$r[\$c] ?? \"\"));
        if (\$v !== \"\") \$referenced[\$v] = true;
    }
}
\$dir = \"/var/www/html/uploads/works\";
\$orphans = []; \$bytes = 0;
foreach (scandir(\$dir) as \$f) {
    if (\$f === \".\" || \$f === \"..\") continue;
    \$ext = strtolower(pathinfo(\$f, PATHINFO_EXTENSION));
    if (!in_array(\$ext, [\"jpg\",\"jpeg\",\"png\",\"gif\"], true)) continue;
    if (isset(\$referenced[\$f])) continue;
    \$orphans[] = \$f;
    \$bytes += (int)@filesize(\$dir . \"/\" . \$f);
}
echo \"orphan jpg/png/gif files: \" . count(\$orphans) . PHP_EOL;
echo \"total bytes: \" . number_format(\$bytes) . \" (\" . round(\$bytes/1024/1024, 1) . \" MB)\" . PHP_EOL;
echo \"sample (first 5): \" . implode(\", \", array_slice(\$orphans, 0, 5)) . PHP_EOL;
"'

docker compose exec -T web bash -lc 'cd /var/www/html && php -r "
require \"config/setup.php\"; require \"src/Database/DB.php\";
\$pdo = \\Database\\DB::getInstance();
\$cols = [\"thumb_image\",\"file_attach1\",\"file_attach2\",\"file_attach3\",\"file_attach4\",\"file_attach5\"];
\$referenced = [];
foreach (\$pdo->query(\"SELECT \" . implode(\",\", \$cols) . \" FROM nb_works\") as \$r) {
    foreach (\$cols as \$c) {
        \$v = trim((string)(\$r[\$c] ?? \"\"));
        if (\$v !== \"\") \$referenced[\$v] = true;
    }
}
\$dir = \"/var/www/html/uploads/works\";
\$deleted = 0; \$failed = 0; \$bytes = 0;
foreach (scandir(\$dir) as \$f) {
    if (\$f === \".\" || \$f === \"..\") continue;
    \$ext = strtolower(pathinfo(\$f, PATHINFO_EXTENSION));
    if (!in_array(\$ext, [\"jpg\",\"jpeg\",\"png\",\"gif\"], true)) continue;
    if (isset(\$referenced[\$f])) continue;
    \$abs = \$dir . \"/\" . \$f;
    \$sz = (int)@filesize(\$abs);
    if (@unlink(\$abs)) { \$deleted++; \$bytes += \$sz; }
    else { \$failed++; fwrite(STDERR, \"[fail] \$f\\n\"); }
}
echo \"deleted: \$deleted\\nfailed: \$failed\\nbytes freed: \" . number_format(\$bytes) . \" (\" . round(\$bytes/1024/1024, 1) . \" MB)\" . PHP_EOL;
"'

docker compose exec -T web bash -lc 'cd /var/www/html && php -r "
require \"config/setup.php\"; require \"src/Database/DB.php\";
\$pdo = \\Database\\DB::getInstance();
\$cols = [\"thumb_image\",\"file_attach1\",\"file_attach2\",\"file_attach3\",\"file_attach4\",\"file_attach5\"];
\$dir = \"/var/www/html/uploads/works\";
\$rows = \$pdo->query(\"SELECT id, \" . implode(\",\", \$cols) . \" FROM nb_works\")->fetchAll(\\PDO::FETCH_ASSOC);
\$report = [];
foreach (\$rows as \$r) {
    foreach (\$cols as \$c) {
        \$v = trim((string)(\$r[\$c] ?? \"\"));
        if (\$v === \"\") continue;
        \$e = strtolower(pathinfo(\$v, PATHINFO_EXTENSION));
        if (\$e === \"webp\") continue;
        \$abs = \$dir . \"/\" . \$v;
        if (!is_file(\$abs)) continue;
        \$sz = @getimagesize(\$abs);
        \$mp = (\$sz && \$sz[0] && \$sz[1]) ? round((\$sz[0]*\$sz[1])/1e6, 1) : 0;
        \$report[] = sprintf(\"id=%-4s %-12s %-30s %sx%s = %sMP  %s KB\",
            \$r[\"id\"], \$c, \$v, \$sz[0] ?? \"?\", \$sz[1] ?? \"?\", \$mp, round(@filesize(\$abs)/1024));
    }
}
usort(\$report, function(\$a, \$b){ return strcmp(\$a, \$b); });
echo \"Total: \" . count(\$report) . PHP_EOL;
echo implode(PHP_EOL, array_slice(\$report, 0, 10)) . PHP_EOL;
echo \"...\" . PHP_EOL;
echo implode(PHP_EOL, array_slice(\$report, -5)) . PHP_EOL;
"'

